// Parse and render rich text safely without innerHTML
function renderRichText(text: string, container: HTMLElement): void {
  // Simple parser that processes text character by character
  let i = 0;
  const stack: HTMLElement[] = [container];

  while (i < text.length) {
    const char = text[i];

    // Check for newline
    if (char === '\n') {
      stack[stack.length - 1].appendChild(document.createElement('br'));
      i++;
      continue;
    }

    // Check for opening tag
    if (char === '<') {
      const tagEnd = text.indexOf('>', i);
      if (tagEnd === -1) {
        // No closing >, treat as text
        stack[stack.length - 1].appendChild(document.createTextNode(char));
        i++;
        continue;
      }

      const tag = text.slice(i, tagEnd + 1);

      // Parse tag
      if (tag === '<b>' || tag === '<strong>') {
        const elem = document.createElement(tag === '<b>' ? 'b' : 'strong');
        stack[stack.length - 1].appendChild(elem);
        stack.push(elem);
        i = tagEnd + 1;
      } else if (tag === '</b>' || tag === '</strong>') {
        if (stack.length > 1) {
          stack.pop();
        }
        i = tagEnd + 1;
      } else if (tag === '<i>' || tag === '<em>') {
        const elem = document.createElement(tag === '<i>' ? 'i' : 'em');
        stack[stack.length - 1].appendChild(elem);
        stack.push(elem);
        i = tagEnd + 1;
      } else if (tag === '</i>' || tag === '</em>') {
        if (stack.length > 1) {
          stack.pop();
        }
        i = tagEnd + 1;
      } else if (tag === '<br>' || tag === '<br/>' || tag === '<br />') {
        stack[stack.length - 1].appendChild(document.createElement('br'));
        i = tagEnd + 1;
      } else if (tag.startsWith('<a href=')) {
        // Parse href
        const hrefMatch = tag.match(/<a href=["']([^"']+)["']>/);
        if (hrefMatch) {
          const elem = document.createElement('a');
          elem.href = hrefMatch[1];
          stack[stack.length - 1].appendChild(elem);
          stack.push(elem);
        }
        i = tagEnd + 1;
      } else if (tag === '</a>') {
        if (stack.length > 1) {
          stack.pop();
        }
        i = tagEnd + 1;
      } else {
        // Unknown tag, treat as text
        stack[stack.length - 1].appendChild(document.createTextNode(char));
        i++;
      }
    } else {
      // Regular text
      stack[stack.length - 1].appendChild(document.createTextNode(char));
      i++;
    }
  }
}

